function heapSort(nums) {
  const heap = [], out = [] //@init
  for (const x of nums) {
    heap.push(x); let i = heap.length - 1 //@push
    while (i > 0 && heap[(i - 1) >> 1] > heap[i]) { //@up
      const p = (i - 1) >> 1; [heap[i], heap[p]] = [heap[p], heap[i]]; i = p //@swapup
    }
  }
  while (heap.length) { //@pop
    out.push(heap[0]) //@take
    const last = heap.pop()
    if (!heap.length) break
    heap[0] = last; let i = 0 //@move
    while (true) {
      let small = i
      for (const c of [2 * i + 1, 2 * i + 2]) if (c < heap.length && heap[c] < heap[small]) small = c //@down
      if (small === i) break
      ;[heap[i], heap[small]] = [heap[small], heap[i]]; i = small //@swapdown
    }
  }
  return out //@done
}

